    #completeWorker(worker: Promise<AccountProviderConfigSnapshot>): void {
        if (this.#inFlight !== worker) {
            return;
        }
        this.#inFlight = undefined;
        if (this.#disposed || this.#pendingReasons.size === 0) {
            return;
        }
        this.#startWorker().catch(() => {});
