    }

    #reject(generation: number, error: unknown): void {
        const remaining: RefreshWaiter[] = [];
        for (const waiter of this.#waiters) {
            if (waiter.generation <= generation) {
                waiter.reject(error);
            } else {
                remaining.push(waiter);
            }
        }
